-- Read only. Run it in the Supabase SQL editor of the project you are checking (DEV or production). It returns ONE jsonb value named inventory.
-- Save that value as actual.json, then the agent runs the compare command of scripts/nav2_schema_inventory.mjs on it.
select jsonb_build_object(
  'columns', (select coalesce(jsonb_agg(jsonb_build_array(c.table_name, c.column_name, c.data_type, c.is_nullable, coalesce(c.column_default, ''), coalesce(c.character_maximum_length, 0), coalesce(c.numeric_precision, 0), coalesce(c.numeric_scale, 0), c.is_identity) order by c.table_name, c.column_name), '[]'::jsonb)
      from information_schema.columns c where c.table_schema = 'public' and (c.table_name in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache') or (c.table_name = 'admin_users' and c.column_name in ('can_switch_risk_free_series', 'can_upload_risk_free_data')))),
  'constraints', (select coalesce(jsonb_agg(jsonb_build_array(cl.relname, k.conname, k.contype::text, pg_get_constraintdef(k.oid)) order by cl.relname, k.conname), '[]'::jsonb)
      from pg_constraint k join pg_class cl on cl.oid = k.conrelid join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and cl.relname in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache')),
  'indexes', (select coalesce(jsonb_agg(jsonb_build_array(i.tablename, i.indexname, i.indexdef) order by i.tablename, i.indexname), '[]'::jsonb)
      from pg_indexes i where i.schemaname = 'public' and i.tablename in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache')),
  'rls', (select coalesce(jsonb_agg(jsonb_build_array(cl.relname, cl.relrowsecurity) order by cl.relname), '[]'::jsonb)
      from pg_class cl join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and cl.relname in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache')),
  'policies', (select coalesce(jsonb_agg(jsonb_build_array(p.tablename, p.policyname, p.cmd, p.roles::text, coalesce(p.qual, ''), coalesce(p.with_check, '')) order by p.tablename, p.policyname), '[]'::jsonb)
      from pg_policies p where p.schemaname = 'public' and p.tablename in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache')),
  'grants', (select coalesce(jsonb_agg(jsonb_build_array(g.table_name, g.grantee, g.privilege_type) order by g.table_name, g.grantee, g.privilege_type), '[]'::jsonb)
      from (select distinct table_name, grantee, privilege_type from information_schema.role_table_grants where table_schema = 'public' and grantee in ('anon', 'authenticated') and table_name in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache')) g),
  'triggers', (select coalesce(jsonb_agg(jsonb_build_array(cl.relname, t.tgname, pg_get_triggerdef(t.oid)) order by cl.relname, t.tgname), '[]'::jsonb)
      from pg_trigger t join pg_class cl on cl.oid = t.tgrelid join pg_namespace n on n.oid = cl.relnamespace where n.nspname = 'public' and not t.tgisinternal and (cl.relname in ('ii_risk_free_batches', 'ii_risk_free_corrections', 'ii_risk_free_observations', 'ii_risk_free_refresh_attempts', 'ii_risk_free_review_items', 'ii_risk_free_series', 'ii_risk_free_series_state_log', 'nav2_correction_events', 'nav2_fund_analytics_reports', 'nav2_report_nav_dependencies', 'nav2_report_render_tokens', 'nav2_result_cache') or cl.relname in ('ii_reference_corrections', 'ii_risk_free_corrections'))),
  'functions', (select coalesce(jsonb_agg(jsonb_build_array(pr.proname, pg_get_function_identity_arguments(pr.oid), pg_get_function_result(pr.oid), pr.prosecdef, pr.provolatile::text,
        md5(pr.prosrc), md5(lower(regexp_replace(regexp_replace(pr.prosrc, '--[^\n]*', '', 'g'), '\s+', '', 'g'))),
        has_function_privilege('anon', pr.oid, 'execute'), has_function_privilege('authenticated', pr.oid, 'execute'), has_function_privilege('service_role', pr.oid, 'execute')) order by pr.proname, pg_get_function_identity_arguments(pr.oid)), '[]'::jsonb)
      from pg_proc pr join pg_namespace n on n.oid = pr.pronamespace where n.nspname = 'public' and pr.proname in ('commit_risk_free_upload', 'correct_risk_free_observation', 'ii_risk_free_append_only', 'ii_risk_free_obs_guard', 'is_risk_free_data_admin', 'is_risk_free_series_switch_admin', 'nav2_ambiguity_case_summary', 'nav2_capture_reference_correction', 'nav2_capture_risk_free_correction', 'nav2_monitor_cell', 'nav2_monitoring_snapshot', 'nav2_refresh_attempt_summary', 'nav2_reports_immutable', 'nav2_viewer_has_premium', 'pc6_nav_row_is_candidate', 'record_risk_free_refresh_results', 'resolve_risk_free_review_item', 'set_risk_free_series_state')),
  'job_keys', (select coalesce(jsonb_agg(jsonb_build_array(j.job_key, j.enabled) order by j.job_key), '[]'::jsonb) from ii_reference_job_control j where j.job_key in ('nav2_correction_worker', 'nav2_fund_analytics', 'nav2_risk_free_weekly_refresh', 'nav2_trigger_planner')),
  'series_seed', (select coalesce(jsonb_agg(jsonb_build_array(s.series_id, s.role, s.cadence, s.max_staleness_days, s.terms_review_status) order by s.series_id), '[]'::jsonb) from ii_risk_free_series s)
) as inventory;
